css:
/* Hide a specific element in print view */
.text-center h4 {
    display: none;
}
.print-format td, .print-format th {
    padding: 4px !important;
}
@page {
    margin-bottom: 30mm;
}

.footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    height: 20mm;
    font-size: 11px;
    border-top: 1px solid #999;
    padding-top: 4mm;
}

.page-number:before {
    content: counter(page);
}

.total-pages:before {
    content: counter(pages);
}
